const body = $input.first().json.body || $input.first().json;
const data = body.data || body;
const key = data.key || {};
const remoteJid = key.remoteJid || '';
const phone = remoteJid.replace('@s.whatsapp.net', '').replace('@g.us', '');
if (key.fromMe) return [];
const message = data.message || {};
const messageType = data.messageType || 'unknown';
let textContent = '';
if (messageType === 'conversation') textContent = message.conversation || '';
else if (messageType === 'extendedTextMessage') textContent = (message.extendedTextMessage || {}).text || '';
else if (messageType === 'audioMessage') textContent = '[رسالة صوتية]';
else textContent = message.conversation || message.text || '';
return [{ json: { phone, remoteJid, messageType, textContent, timestamp: new Date().toISOString() } }];

const phone = $input.first().json.phone;
const isManager = (phone === '380936582617');
return [{ json: { ...$input.first().json, isManager } }];

const phone = $input.first().json.phone;
const textContent = $input.first().json.textContent;
const isManager = $input.first().json.isManager;
const SB = 'https://xfibcjhshpmqkrhlpsoa.supabase.co/rest/v1';
const KEY = 'eyJ-REDACTED-SERVICE-ROLE';
const h = { 'apikey': KEY, 'Authorization': 'Bearer ' + KEY, 'Content-Type': 'application/json' };

let isNew = false, lead = null;
try {
  const d = await this.helpers.httpRequest({
    url: SB + '/leads?phone=eq.' + phone + '&limit=1',
    method: 'GET',
    headers: h
  });
  if (d && d.length > 0) {
    lead = d[0];
    await this.helpers.httpRequest({
      url: SB + '/leads?phone=eq.' + phone,
      method: 'PATCH',
      headers: { ...h, 'Prefer': 'return=minimal' },
      body: { last_contact: new Date().toISOString(), updated_at: new Date().toISOString() }
    });
  } else {
    isNew = true;
    if (!isManager) {
      const r2 = await this.helpers.httpRequest({
        url: SB + '/leads',
        method: 'POST',
        headers: { ...h, 'Prefer': 'return=representation' },
        body: { phone, stage: 'new', assigned_to: 'bot', source: 'direct', last_contact: new Date().toISOString() }
      });
      lead = Array.isArray(r2) ? r2[0] : r2;
    }
  }
} catch(e) {}

if (!isManager) {
  try {
    await this.helpers.httpRequest({
      url: SB + '/conversations',
      method: 'POST',
      headers: { ...h, 'Prefer': 'return=minimal' },
      body: { phone, role: 'user', message: textContent }
    });
  } catch(e) {}
}

return [{ json: { ...$input.first().json, isNew, lead } }];

const phone = $input.first().json.phone;
const isManager = $input.first().json.isManager;
const isNew = $input.first().json.isNew;
const lead = $input.first().json.lead;
const SB = 'https://xfibcjhshpmqkrhlpsoa.supabase.co/rest/v1';
const KEY = 'eyJ-REDACTED-SERVICE-ROLE';
const h = { 'apikey': KEY, 'Authorization': 'Bearer ' + KEY };

let chatHistory = '';
if (!isManager) {
  try {
    const msgs = await this.helpers.httpRequest({
      url: SB + '/conversations?phone=eq.' + phone + '&order=created_at.desc&limit=20',
      method: 'GET', headers: h
    });
    chatHistory = (msgs || []).reverse().map(m => (m.role === 'user' ? 'العميل' : 'ليلى') + ': ' + m.message).join('\n');
  } catch(e) {}
}

let managerInstructions = '';
try {
  const inst = await this.helpers.httpRequest({
    url: SB + '/manager_instructions?active=eq.true&order=created_at.desc&limit=20',
    method: 'GET', headers: h
  });
  if (inst && inst.length > 0) managerInstructions = inst.map(i => '- ' + i.instruction).join('\n');
} catch(e) {}

let leadContext = '';
if (isManager) {
  leadContext = 'هذا المدير أبو أمير.';
} else if (isNew) {
  leadContext = 'هذا عميل جديد — عرّفي نفسك.';
} else {
  leadContext = 'عميل سابق — لا تعرّفي نفسك.';
  if (lead?.name) leadContext += ' اسمه: ' + lead.name + '.';
  if (lead?.destination) leadContext += ' الوجهة: ' + lead.destination + '.';
}

return [{ json: { ...$input.first().json, chatHistory, leadContext, managerInstructions } }];

const aiResp = $input.first().json;
const content = aiResp.choices?.[0]?.message?.content || '';
const phone = $('Parse Message').first().json.phone;
const remoteJid = $('Parse Message').first().json.remoteJid;
const WA_LINK = 'https://wa.me/380936582617';

// ── مانع الأسعار المخترعة ───────────────────────────────────────────────────
const hasPricingTag = /\[PRICING:/i.test(content);
const hasHotelTag   = /\[HOTEL_PRICING:/i.test(content);
const looksLikePrices = /💰|\$\d{3,}|السعر الإجمالي|الباقة الاقتصادية|الباقة الفضية|الباقة الذهبية/.test(content);
if (looksLikePrices && !hasPricingTag && !hasHotelTag) {
  return [{ json: { phone, remoteJid, response: `عشان أساعدك بأفضل شكل، تقدر تتواصل مع فريقنا المختص مباشرة: ${WA_LINK} 😊` } }];
}

// ── HOTEL_PRICING ────────────────────────────────────────────────────────────
const hotelMatch = content.match(/\[HOTEL_PRICING:\s*hotel=(.+?),\s*destination=([A-Z]{2,3}),\s*city=([\w\s]+),\s*nights=(\d+),\s*adults=(\d+),\s*children=([\d,]*),\s*type=(\w+)\]/i);
if (hotelMatch) {
  try {
    const hotelReq = {
      hotelName: hotelMatch[1].trim(), destination: hotelMatch[2].trim(), city: hotelMatch[3].trim(),
      nights: parseInt(hotelMatch[4]), adults: parseInt(hotelMatch[5]),
      childrenAges: hotelMatch[6] ? hotelMatch[6].split(',').map(Number).filter(n=>n>0) : [],
      clientType: hotelMatch[7]||'B2C', roomCategory: 'all'
    };
    const pricing = await this.helpers.httpRequest({ url:'https://n8n.arcadia-tour.cloud/webhook/pricing-engine', method:'POST', headers:{'Content-Type':'application/json'}, body: hotelReq });
    if (!pricing.ok || !pricing.rooms || pricing.rooms.length===0) {
      const r2 = await this.helpers.httpRequest({ url:'https://openrouter.ai/api/v1/chat/completions', method:'POST',
        headers:{'Authorization':'Bearer REDACTED_API_KEY','Content-Type':'application/json'},
        body:{ model:'openai/gpt-4o-mini', temperature:0.7, max_tokens:200,
          messages:[{role:'system',content:'أنتِ ليلى من أركاديا. الفندق ما لقيتيه. اسأليه يكتب الاسم بالإنجليزي. ممنوع تخترعي سعر. لا تكتبي اسمك.'},{role:'user',content:'العميل طلب: '+hotelMatch[1]}]}
      });
      return [{ json: { phone, remoteJid, response: r2.choices?.[0]?.message?.content||'ممكن تكتب اسم الفندق بالإنجليزي؟ 😊' } }];
    }
    const { hotelName, stars, nights, adults, rooms } = pricing;
    const DEST = { KZ:['كازاخستان','🇰🇿'], RU:['روسيا','🇷🇺'], PL:['بولندا','🇵🇱'], UZ:['أوزبكستان','🇺🇿'] };
    const [dn,fl] = DEST[hotelReq.destination]||[hotelReq.destination,''];
    let msg = `🏨 ${hotelName} ${'⭐'.repeat(Math.min(stars||5,5))}\n━━━━━━━━━━━━━━━\n📍 ${hotelReq.city} — ${dn} ${fl}\n🗓 ${(nights||7)+1} أيام / ${nights} ليالٍ\n👥 ${adults+(hotelReq.childrenAges.length)} أشخاص\n━━━━━━━━━━━━━━━\n✅ يشمل: إقامة + إفطار + استقبال مطار + سيارة خاصة + جولات\n━━━━━━━━━━━━━━━\n\n🛏 أنواع الغرف المتاحة:\n\n`;
    for (const r of rooms) msg += `🔹 ${r.roomType}\n   💰 السعر الإجمالي: $${r.totalUSD.toLocaleString()}\n\n`;
    msg += `⚠️ العرض صالح 3 أيام | حسب التوفر\nأي غرفة تناسبك؟ 😊`;
    return [{ json: { phone, remoteJid, response: msg } }];
  } catch(e) {
    return [{ json: { phone, remoteJid, response: 'ممكن تكتب اسم الفندق بالإنجليزي؟ 😊' } }];
  }
}

// ── PRICING ──────────────────────────────────────────────────────────────────
const pm = content.match(/\[PRICING:\s*destination=([A-Z]{2,3}),\s*city=([\w\s]+),\s*nights=(\d+),\s*adults=(\d+),\s*children=([\d,]*)(?:,\s*type=(\w+))?(?:,\s*route=(\w+))?(?:,\s*tours=(\d+))?(?:,\s*exclude=([^\]]+))?\]/i);
if (pm) {
  try {
    const destCode=pm[1].trim(), city=pm[2].trim(), nights=parseInt(pm[3]), adults=parseInt(pm[4]);
    const children = pm[5] ? pm[5].split(',').map(Number).filter(n=>n>0) : [];
    const clientType=pm[6]||'B2C', route=pm[7]||'standard';
    const tours = pm[8]?parseInt(pm[8]):undefined;
    const exclude = pm[9] ? pm[9].split(',').map(s=>s.trim()).filter(Boolean) : [];
    // isExcludeMode فقط لو في exclude حقيقي ولو سبق وعُرضت أسعار في المحادثة
    const chatCtx = $('Get Context').first().json?.chatHistory || '';
    const pricesPreviouslyShown = /💰|الباقة الاقتصادية|خيار إضافي/.test(chatCtx);
    const isExcludeMode = exclude.length > 0 && pricesPreviouslyShown;

    const body2 = { destination:destCode, city, nights, adults, childrenAges:children, clientType, route };
    if (tours!==undefined) body2.tours=tours;
    if (exclude.length>0) body2.exclude=exclude;

    const pricing = await this.helpers.httpRequest({ url:'https://n8n.arcadia-tour.cloud/webhook/pricing-engine', method:'POST', headers:{'Content-Type':'application/json'}, body:body2 });

    // noMore
    if (pricing.ok && pricing.noMore) {
      return [{ json: { phone, remoteJid, response: `ما في خيارات إضافية متاحة حالياً. لو تبي مساعدة أكثر، تقدر تتواصل مع فريقنا: ${WA_LINK} 😊` } }];
    }

    if (pricing.ok && pricing.packages && pricing.packages.length>0) {
      const pkgs = pricing.packages;
      const days=nights+1, tourDays=tours!==undefined?tours:Math.max(nights-1,1);
      const totalPax=adults+children.length, isBasic=route==='basic';
      const DEST={KZ:['كازاخستان','🇰🇿'],RU:['روسيا','🇷🇺'],PL:['بولندا','🇵🇱'],UZ:['أوزبكستان','🇺🇿']};
      const [destName,flag]=DEST[destCode]||[destCode,''];
      const simLine=(destCode!=='RU'&&!isBasic)?'\n• شرائح اتصال وإنترنت':'';
      const toursLine=isBasic?'':`\n• ${tourDays} جولات بسيارة خاصة وسائق خاص`;

      if (isExcludeMode) {
        // ── خيار واحد بس ────────────────────────────────────────────────────
        const p = pkgs[0];
        const sysMsg = `أنتِ ليلى من أركاديا. اعرضي هالفندق كخيار إضافي — فندق واحد بس بهالتنسيق. لا تكتبي "ليلى:" في البداية.

🏨 خيار إضافي — ${destName} ${flag}
━━━━━━━━━━━━━━━
📍 ${city} — ${nights} ليالٍ
🏨 [HOTEL] ⭐[STARS]
💰 السعر الإجمالي: $[PRICE]
✅ يشمل: إقامة + إفطار يومي + استقبال مطار + سيارة خاصة + جولات${simLine}

تناسبك هالباقة؟ أو تبي خيار ثاني؟ 😊`;
        const pkgLine = `${p.tierAr}|${p.hotelName}|${p.stars}|${p.totalUSD}`;
        const r2 = await this.helpers.httpRequest({ url:'https://openrouter.ai/api/v1/chat/completions', method:'POST',
          headers:{'Authorization':'Bearer REDACTED_API_KEY','Content-Type':'application/json'},
          body:{ model:'openai/gpt-4o-mini', temperature:0.3, max_tokens:400,
            messages:[{role:'system',content:sysMsg},{role:'user',content:'الفندق:\n'+pkgLine}]}
        });
        return [{ json: { phone, remoteJid, response: r2.choices?.[0]?.message?.content||'' } }];
      }

      // ── 3 باقات عادية ────────────────────────────────────────────────────
      const sysMsg = `أنتِ ليلى من أركاديا. اعرضي الباقات بهالشكل بالضبط. لا تكتبي "ليلى:" في البداية.

🏨 عرض سعر ${destName} ${flag}${isBasic?' (باقة مختصرة بدون جولات)':''}
━━━━━━━━━━━━━━━
📍 ${city}
🗓 ${days} أيام / ${nights} ليالٍ
👥 ${totalPax} أشخاص
━━━━━━━━━━━━━━━
✅ يشمل:
• الإقامة في الفندق + الإفطار اليومي
• استقبال وتوديع من المطار${toursLine}${simLine}

🥉 الباقة الاقتصادية
━━━━━━━━━━━━━━━
📍 ${city} — ${nights} ليالٍ
🏨 [HOTEL_ECO] ⭐[STARS_ECO]
السعر الإجمالي: 💰 $[PRICE_ECO]

🥈 الباقة الفضية
━━━━━━━━━━━━━━━
📍 ${city} — ${nights} ليالٍ
🏨 [HOTEL_SIL] ⭐[STARS_SIL]
السعر الإجمالي: 💰 $[PRICE_SIL]

🥇 الباقة الذهبية
━━━━━━━━━━━━━━━
📍 ${city} — ${nights} ليالٍ
🏨 [HOTEL_GOLD] ⭐[STARS_GOLD]
السعر الإجمالي: 💰 $[PRICE_GOLD]

⚠️ العرض صالح 3 أيام | حسب التوفر للغرف
أي باقة تناسبك أكثر؟ 😊`;

      const pkgLines = pkgs.map(p=>`${p.tierAr}|${p.hotelName}|${p.stars}|${p.totalUSD}`).join('\n');
      const r2 = await this.helpers.httpRequest({ url:'https://openrouter.ai/api/v1/chat/completions', method:'POST',
        headers:{'Authorization':'Bearer REDACTED_API_KEY','Content-Type':'application/json'},
        body:{ model:'openai/gpt-4o-mini', temperature:0.3, max_tokens:1024,
          messages:[{role:'system',content:sysMsg},{role:'user',content:'البيانات:\n'+pkgLines}]}
      });
      return [{ json: { phone, remoteJid, response: r2.choices?.[0]?.message?.content||content } }];
    }

    return [{ json: { phone, remoteJid, response: `عشان أساعدك بأفضل شكل، تقدر تتواصل مع فريقنا المختص: ${WA_LINK} 😊` } }];
  } catch(e) {
    return [{ json: { phone, remoteJid, response: `عشان أساعدك بأفضل شكل، تقدر تتواصل مع فريقنا: ${WA_LINK} 😊` } }];
  }
}

return [{ json: { phone, remoteJid, response: content } }];

const phone = $input.first().json.phone;
const response = $input.first().json.response;
const remoteJid = $input.first().json.remoteJid;
const isManager = $('Manager or Customer').first().json.isManager;
const SB = 'https://xfibcjhshpmqkrhlpsoa.supabase.co/rest/v1';
const KEY = 'eyJ-REDACTED-SERVICE-ROLE';
const h = { 'apikey': KEY, 'Authorization': 'Bearer ' + KEY, 'Content-Type': 'application/json', 'Prefer': 'return=minimal' };

if (!isManager) {
  try {
    await this.helpers.httpRequest({
      url: SB + '/conversations',
      method: 'POST', headers: h,
      body: { phone, role: 'assistant', message: response }
    });
  } catch(e) {}
}

if (isManager) {
  const txt = $('Parse Message').first().json.textContent;
  const isQuestion = txt.includes('؟') || txt.includes('?') || txt.startsWith('كم') || txt.startsWith('وش') || txt.startsWith('ايش') || txt.startsWith('شو');
  if (!isQuestion) {
    try {
      await this.helpers.httpRequest({
        url: SB + '/manager_instructions',
        method: 'POST', headers: h,
        body: { instruction: txt, active: true, created_at: new Date().toISOString() }
      });
    } catch(e) {}
  }
}

return [{ json: { phone, remoteJid, response } }];
